export const DRIVE_IMAGE_BASE = 'https://drive.google.com/uc?export=view&id=';

export function getProductImageUrl(asset: string): string | null {
  const fileId = imageMapping[asset];
  if (fileId) {
    return `${DRIVE_IMAGE_BASE}${fileId}`;
  }
  return null;
}